/*
 * A072844  Number of words of length 2n-1 generated by the two letters s and
 *          t that reduce to the identity 1 by using the relations sssssss=1,
 *          tt=1 and stst=1. The generators s and t along with the three
 *          relations generate the 14-element dihedral group D7.
 * https://oeis.org/A072844
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = 9*a(n-1) - 26*a(n-2) + 25*a(n-3) - 4*a(n-4); Initial
 *            values: a(1)=0, a(2)=0, a(3)=0, a(4)=1
 * Range:     u8 n <= 6, u16 n <= 10, u32 n <= 18, u64 n <= 25, u128 n <= 25,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stddef.h>

static seq_t *cache = NULL;
static size_t cache_cap = 0;
static idx_t cache_len = 0;

static void init_cache(void) {
    if (cache == NULL) {
        cache_cap = 16;
        cache = (seq_t *)malloc(cache_cap * sizeof(seq_t));
        cache_len = 0;
    }
}

seq_t a(idx_t n) {
    init_cache();

    /* Ensure initial values are present */
    if (cache_len == 0) {
        if (cache_cap < 4) {
            size_t new_cap = 4;
            seq_t *new_mem = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
            if (!new_mem) return 0; /* allocation failed */
            cache = new_mem;
            cache_cap = new_cap;
        }
        cache[0] = 0; /* a(1) */
        cache[1] = 0; /* a(2) */
        cache[2] = 0; /* a(3) */
        cache[3] = 1; /* a(4) */
        cache_len = 4;
    }

    if (n <= cache_len) {
        return cache[n - 1];
    }

    /* Extend cache up to the desired index using the recurrence */
    for (idx_t i = cache_len; i < n; ++i) {
        seq_t p0 = cache[i - 4];
        seq_t p1 = cache[i - 3];
        seq_t p2 = cache[i - 2];
        seq_t p3 = cache[i - 1];

        seq_t res = 9 * p3 + 25 * p1;
        res -= 26 * p2;
        res -= 4 * p0;

        if (cache_len == cache_cap) {
            size_t new_cap = cache_cap * 2;
            seq_t *new_mem = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
            if (!new_mem) return 0; /* allocation failed */
            cache = new_mem;
            cache_cap = new_cap;
        }
        cache[cache_len++] = res;
    }

    return cache[n - 1];
}
